import sys
from collections import deque

class TreeNode:
    __slots__ = ('val', 'left', 'right')
    def __init__(self, val=0, left=None, right=None):
        self.val = val; self.left = left; self.right = right

def build_tree(arr):
    if not arr or arr[0] == 'n':
        return None
    root = TreeNode(int(arr[0]))
    q = deque([root])
    i = 1
    while q and i < len(arr):
        node = q.popleft()
        if i < len(arr) and arr[i] != 'n':
            node.left = TreeNode(int(arr[i]))
            q.append(node.left)
        i += 1
        if i < len(arr) and arr[i] != 'n':
            node.right = TreeNode(int(arr[i]))
            q.append(node.right)
        i += 1
    return root

def inorder_best(root):
    res = []
    cur = root
    while cur:
        if cur.left is None:
            res.append(cur.val)
            cur = cur.right
        else:
            pre = cur.left
            while pre.right and pre.right is not cur:
                pre = pre.right
            if pre.right is None:
                pre.right = cur
                cur = cur.left
            else:
                pre.right = None
                res.append(cur.val)
                cur = cur.right
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    arr = data[1:1 + n]
    root = build_tree(arr)
    print(' '.join(map(str, inorder_best(root))))
